import torch
import torch.nn as nn
import torch.nn.utils.prune as prune
import copy

class MLP(nn.Module):
    def __init__(self):
        super().__init__()
        self.fc1 = nn.Linear(20, 50)
        self.fc2 = nn.Linear(50, 2)
    def forward(self, x):
        return self.fc2(torch.relu(self.fc1(x)))

model = MLP()
# Save initial weights for the "lottery ticket" reset step
initial_state = copy.deepcopy(model.state_dict())

optimizer = torch.optim.Adam(model.parameters(), lr=1e-3)
criterion = nn.CrossEntropyLoss()

target_sparsity = 0.9
n_epochs = 10

for epoch in range(n_epochs):
    # Linear schedule: 0% at epoch 0, target_sparsity at final epoch
    current_sparsity = target_sparsity * (epoch / (n_epochs - 1))

    for module in model.modules():
        if isinstance(module, nn.Linear):
            prune.l1_unstructured(module, name="weight", amount=current_sparsity)

    # One training step (dummy data)
    x = torch.randn(16, 20)
    y = torch.randint(0, 2, (16,))
    optimizer.zero_grad()
    loss = criterion(model(x), y)
    loss.backward()
    optimizer.step()

    # Remove old pruning reparam before applying next epoch's mask fresh
    for module in model.modules():
        if isinstance(module, nn.Linear) and prune.is_pruned(module):
            prune.remove(module, "weight")

    print(f"epoch {epoch}: sparsity={current_sparsity:.2f}, loss={loss.item():.4f}")

# Lottery ticket step: reset surviving weights to their ORIGINAL init values
final_mask = {}
for name, module in model.named_modules():
    if isinstance(module, nn.Linear):
        final_mask[name] = (module.weight.data != 0).float()

model.load_state_dict(initial_state)  # reset all weights to initial values
for name, module in model.named_modules():
    if isinstance(module, nn.Linear):
        module.weight.data *= final_mask[name]  # re-apply the found mask
print("Winning ticket subnetwork reset to initial weights.")
